def close(x, ref, rtol: float = 1e-12, atol: float = 1e-13) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if not (u == v or abs(u - v) <= atol + rtol * abs(v)):
            print('mismatch', u, v)
            ok = False
    return ok

def check(ok: bool, what: str):
    if not ok:
        print('TEST FAILED:', what)

