sq = squareform(pdist(Xa))
check(sq.shape == (7, 7) and sq[2, 5] == sq[5, 2] and sq[3, 3] == 0.0, 'squareform matrix')
check(close(squareform(sq), PD_euclidean), 'squareform vector')
check(close(squareform(np.zeros(0)), [[0.0]]), 'squareform empty')
check(is_valid_dm(sq) and not is_valid_dm(np.ones((3, 3))), 'is_valid_dm')
def raises(f) -> bool:
    try:
        f()
    except ValueError:
        return True
    return False
check(raises(lambda: squareform(np.ones(4))), 'squareform bad size')
check(raises(lambda: squareform(np.ones((3, 3)))), 'squareform checks')
check(squareform(np.ones((3, 3)), checks=False).shape == (3,), 'squareform no checks')
check(raises(lambda: squareform(sq, force='tomatrix')), 'force tomatrix')
check(raises(lambda: pdist(Xa, 'nosuch')), 'unknown metric')
check(raises(lambda: cdist(Xa, Ba)), 'cdist dims')
check(raises(lambda: is_valid_dm(np.ones((2, 2)), throw=True)), 'is_valid_dm throw')
check(raises(lambda: pdist(Xa[:3], 'mahalanobis')), 'mahalanobis singular')

# KDTree
t = KDTree(Pa, leafsize=4)
check(t.n == 40 and t.m == 2, 'tree attrs')
d1, i1 = t.query(Qa)
check(close(d1, KQ1_d) and close(i1, KQ1_i), 'query k=1')
d3, i3 = t.query(Qa, k=3)
check(close(d3, KQ3_d) and close(i3, KQ3_i), 'query k=3')
dub, iub = t.query(Qa, k=4, p=1.0, distance_upper_bound=1.2)
check(close(dub, KQub_d) and close(iub, KQub_i), 'query ub')
dinf, iinf = t.query(Qa, k=2, p=inf)
check(close(dinf, KQinf_d) and close(iinf, KQinf_i), 'query pinf')
ds, js = t.query(Qa[0])
check(close(ds, KQ1_d[0]) and js == KQ1_i[0], 'query single')
dk, ik = t.query(Qa[1], k=3)
check(close(dk, KQ3_d[1]) and close(ik, KQ3_i[1]), 'query single k')
bp = t.query_ball_point(Qa, 1.5)
ok = len(bp) == len(KB)
for q in range(len(KB)):
    ok = ok and bp[q] == KB[q]
check(ok, 'query_ball_point')
check(t.query_ball_point(Qa[0], 1.5) == KB[0], 'ball single')
check(t.query_ball_point(Qa[0], 1.5, return_length=True) == len(KB[0]), 'ball length')
pairs = sorted(list(t.query_pairs(0.8)))
check(pairs == KP, 'query_pairs')
check(t.count_neighbors(cKDTree(Qa), 2.0) == KC, 'count_neighbors')
for ls in (1, 2, 16, 100):
    tt = cKDTree(Pa, leafsize=ls)
    dd, ii = tt.query(Qa, k=3)
    check(close(dd, KQ3_d) and close(ii, KQ3_i), 'leafsize')
    tb = KDTree(Pa, leafsize=ls, balanced_tree=False)
    dd, ii = tb.query(Qa, k=3)
    check(close(dd, KQ3_d) and close(ii, KQ3_i), 'unbalanced')
check(raises(lambda: t.query(Qa, p=0.5)), 'bad p')
check(raises(lambda: t.query(np.ones(3))), 'bad dim')
check(raises(lambda: KDTree(Pa, leafsize=0)), 'bad leafsize')
check(close(distance_matrix(Xa, Ya, p=1.5), DM), 'distance_matrix')
check(close(minkowski_distance(Xa[0], Xa[1], 3.0), PD_mink3[0]), 'minkowski_distance')
check(close(minkowski_distance(Xa[:2], Ya[:2]), [CD_euclidean[0][0], CD_euclidean[1][1]]), 'minkowski_distance 2d')
print('done')
